parameters.jsCode:
const { createHmac, timingSafeEqual } = require('crypto');

for (const item of $input.all()) {
  const secret = String(item.json.webhook_secret || '');
  if (!secret) continue;

  const webhookItem = $('Applaud Webhook').first();
  const headers = webhookItem.json.headers || {};
  const header = headers['x-applaud-signature'] || '';

  if (!header) {
    throw new Error('HMAC verification failed: X-Applaud-Signature header missing (is a secret set in Applaud Settings?)');
  }

  let rawBuffer;
  if (webhookItem.binary && webhookItem.binary.data && webhookItem.binary.data.data) {
    rawBuffer = Buffer.from(webhookItem.binary.data.data, 'base64');
  } else if (Buffer.isBuffer(webhookItem.json.body)) {
    rawBuffer = webhookItem.json.body;
  } else if (typeof webhookItem.json.body === 'string') {
    rawBuffer = Buffer.from(webhookItem.json.body, 'utf8');
  } else {
    throw new Error('HMAC verification: raw body not available — ensure the Applaud Webhook node has the rawBody option enabled');
  }

  const expected = 'sha256=' + createHmac('sha256', secret).update(rawBuffer).digest('hex');
  const a = Buffer.from(header);
  const b = Buffer.from(expected);
  if (a.length !== b.length || !timingSafeEqual(a, b)) {
    throw new Error('HMAC verification failed: signature mismatch');
  }

  try {
    item.json.body = JSON.parse(rawBuffer.toString('utf8'));
  } catch (err) {
    // leave body as-is; downstream will surface a natural error
  }
}

return $input.all();

